-- C04 CONTAINMENT — WRITES. Generated by build-and-verify.py; do not edit by hand.
-- Incident use only, on the coordinator's decision, after PROMO_PACKAGE_TOTAL_ENABLED is off and redeployed
-- (that stops new package promos; this stops existing ones from pricing). One transaction.
-- Only flips is_active to false on ACTIVE package-total promos and records each one's fingerprint and row version
-- for 07. Re-running freezes every package promo active at that moment (including one a manager re-activated after
-- a recorded decision) and replaces that promo's earlier record.
-- Never touches sales, receipts, stock, journals, legacy promos or any other promo field; restores nothing.
-- Stops (nothing changes) if the installed C04 objects differ from the tested build.
begin;
set local lock_timeout = '5s';
set local timezone = 'UTC';
do $contain$
begin
  if to_regprocedure('public.assert_active_package_promo_target()') is null
     or (select md5(prosrc) from pg_proc where oid = to_regprocedure('public.assert_active_package_promo_target()')) is distinct from '56845e957b2bdeac4e84d2e852623cf6'
     or (select count(*) from pg_trigger t where t.tgenabled = 'O' and t.tgfoid = to_regprocedure('public.assert_active_package_promo_target()')
         and ((t.tgname = 'promo_package_target_header_guard' and t.tgrelid = 'public.promos'::regclass)
           or (t.tgname = 'promo_package_target_items_guard' and t.tgrelid = 'public.promo_items'::regclass))) <> 2
     or not exists (select 1 from pg_constraint where conname = 'promos_discount_mode_valid' and conrelid = 'public.promos'::regclass) then
    raise exception 'C04_INSTALL_DRIFT: C04 objects differ from the tested build; stop and send this to the developer';
  end if;
  create schema if not exists ops_c04;
  revoke all on schema ops_c04 from public, anon, authenticated, service_role;
  create table if not exists ops_c04.frozen_package_promos (
    promo_id uuid primary key,
    frozen_at timestamptz not null default now(),
    row_fingerprint text not null,
    targets text not null,
    row_version text not null,
    thawed_at timestamptz,
    resolution text
  );
  revoke all on table ops_c04.frozen_package_promos from public, anon, authenticated, service_role;
  lock table ops_c04.frozen_package_promos in share row exclusive mode;  -- 06 and 07 never interleave
  -- One statement: exactly the rows deactivated are recorded (fingerprint excludes is_active, so the
  -- returned post-update row fingerprints the same as before the flip).
  with frozen as (
    update public.promos p set is_active = false
    where p.rule->>'discount_mode' = 'package_total' and p.is_active
    returning p.id, md5((to_jsonb(p) - 'is_active')::text) as row_fingerprint, coalesce((select string_agg(i.item_id::text, ',' order by i.item_id) from public.promo_items i where i.promo_id = p.id), '') as targets, p.xmin::text as row_version
  )
  insert into ops_c04.frozen_package_promos as f (promo_id, row_fingerprint, targets, row_version)
  select id, row_fingerprint, targets, row_version from frozen
  on conflict (promo_id) do update set frozen_at = now(), row_fingerprint = excluded.row_fingerprint,
    targets = excluded.targets, row_version = excluded.row_version, thawed_at = null, resolution = null;
end $contain$;
-- Result: frozen promos still waiting for a decision (ids stay in this SQL Editor session only).
select promo_id, frozen_at from ops_c04.frozen_package_promos where thawed_at is null order by promo_id;
commit;
